// Seed music catalog — GPT는 primary_lane_id만 고르고, backend가 이 catalog에서 트랙을 선택한다.
// source of truth: scratch/seed-catalog-raw.txt (20개 official curation lane, lane당 30곡)
//
// To reduce YouTube API usage, manually add youtubeVideoId to any catalog track.
// Example:
//   youtubeVideoId: "zwf5MpcuKDM"
// Use only the video id, not the full YouTube URL.
// Tracks without youtubeVideoId keep working as before — analyze-and-search falls back
// to YouTube search for the lane until enough verified video ids are filled in.

export type TrackEnergy = "low" | "medium" | "high";

// Step 2 accepted 30-dimension profile (docs/music-catalog-stats-correction-draft.ts).
// 10 atmosphere dims + 7 desired-sound dims, each on a 0-100 scale.
export type TrackStats = {
  brightness: number;
  warmth: number;
  openness: number;
  motion: number;
  intimacy: number;
  socialEnergy: number;
  tension: number;
  nostalgia: number;
  playfulness: number;
  dreaminess: number;

  energy: number;
  groove: number;
  density: number;
  acousticness: number;
  electronicness: number;
  vocalPresence: number;
  climaxIntensity: number;
};

// 4 season dims + 5 time-of-day dims + 4 weather dims, each on a 0-100 scale.
export type TrackAffinity = {
  spring: number;
  summer: number;
  autumn: number;
  winter: number;

  morning: number;
  day: number;
  dusk: number;
  night: number;
  lateNight: number;

  clear: number;
  cloudy: number;
  rain: number;
  snow: number;
};

export type CatalogSeedTrack = {
  laneId: string;
  title: string;
  artist: string;
  // 미리 검증된 YouTube videoId — 채워지면 analyze-and-search가 해당 lane에서
  // YouTube search API 호출 없이 이 값을 바로 사용한다. 수동으로 한 곡씩 채워나간다.
  youtubeVideoId?: string;
  energy: TrackEnergy;
  moodTags: string[];
  sceneTags: string[];
  subTags?: string[];
  // Step 2 accepted stat/affinity enrichment (docs/music-catalog-stats-correction-draft.ts).
  // Optional: passive schema support only, no consumer reads these yet.
  stats?: TrackStats;
  affinity?: TrackAffinity;
  alternateVideoIds?: string[];
  statConfidence?: number;
  needsStatReview?: boolean;
  statReviewNotes?: string[];
};

